function tokenUpdate(data) {
  canvas.tokens.controlled.map(token => token.document.update({light: data}));
}

let torchAnimation = {"type": "torch", "speed": 6, "intensity": 1, "reverse": false};

let dialogEditor = new Dialog({
  title: `Token Light Picker`,
  content: `Pick the light source the selected token is holding.`,
  buttons: {
    none: {
      label: `None`,
      callback: () => {
        tokenUpdate({"color": "#ffffff", "dim": 0, "bright": 0, "angle": 360, "luminosity": 0.5});
        dialogEditor.render(true);
      }
    },
    torch: {
      label: `Torch`,
      callback: () => {
        tokenUpdate({"color": "#f65904","dim": 20, "bright": 10, "angle": 360, "luminosity": 0.5, "animation": torchAnimation});
        dialogEditor.render(true);
      },
    },
    light: {
      label: `Chemical Light`,
      callback: () => {
        tokenUpdate({"color": "#fbff00", "dim": 30, "bright": 20, "angle": 360, "luminosity": 0.5, "animation": {"type": "fog", "speed": 3, "intensity": 6, "reverse": false}});        
        dialogEditor.render(true);
      }
    },
    lamp: {
      label: `Flashlight`,
      callback: () => {
        tokenUpdate({"color": "#ffffff", "dim": 40, "bright": 25, "angle": 65, "luminosity": 0.5, "luminosity": 0.5, "animation": {"type": "fog", "speed": 1, "intensity": 1, "reverse": false}});
        dialogEditor.render(true);
      }
    },
    lamp2: {
      label: `Scary Flashlight`,
      callback: () => {
        tokenUpdate({"color": "#ffffff", "dim": 18, "bright": 5, "angle": 65, "luminosity": 0.5, "luminosity": 0.5, "animation": {"type": "fog", "speed": 5, "intensity": 1, "reverse": false}});
        dialogEditor.render(true);
      }
    }
  },

  default: "close",
  close: () => {}
});

dialogEditor.render(true);
